"""Forward SDK chat session usage to AgentPulse's statusline endpoint.

Claude Agent SDK ``ResultMessage`` payloads are per-query, but
AgentPulse's ``/statusline/claude`` endpoint expects session-cumulative
totals in the same nested shape the Claude Code CLI's statusline hook
emits. ``SessionAccumulator`` sums per-query values across a session;
``build_payload`` produces the dict to POST.
"""

from __future__ import annotations

import logging
import re
from typing import Any

from agentpulse.client import Session

logger = logging.getLogger(__name__)

DEFAULT_CONTEXT_WINDOW = 200_000
_1M_CONTEXT_WINDOW = 1_000_000

# Matches any Claude model id containing a ``[1m]`` context-window tag,
# with optional dated suffix. Structural — no per-model enumeration.
_1M_RE = re.compile(r"\[1m\]")


def lookup_context_window(model_name: str) -> int:
    """Return the context window size for a Claude model.

    Any model whose id contains ``[1m]`` gets 1M; all others get 200k.
    Unknown or empty names fall back to ``DEFAULT_CONTEXT_WINDOW`` and
    emit a warning so the lookup table can be updated.
    """
    if not model_name:
        return DEFAULT_CONTEXT_WINDOW
    if _1M_RE.search(model_name):
        return _1M_CONTEXT_WINDOW
    if re.match(r"^claude-", model_name):
        return DEFAULT_CONTEXT_WINDOW
    logger.warning(
        "unknown Claude model %r; defaulting context window to %d",
        model_name,
        DEFAULT_CONTEXT_WINDOW,
    )
    return DEFAULT_CONTEXT_WINDOW


def extract_model_name(model_usage: dict[str, Any] | None) -> str:
    """Pull the model identifier out of a ``ResultMessage.model_usage`` dict.

    The SDK forwards the CLI's ``model_usage`` map keyed by model id.
    When multiple models appear (rare), the one with the most output
    tokens wins. Model id is used as the deterministic tiebreaker when
    token counts are equal (or absent) so the result doesn't depend on
    dict iteration order.
    """
    if not model_usage:
        return ""
    if len(model_usage) == 1:
        return next(iter(model_usage))

    def _output_tokens(value: Any) -> int:
        if isinstance(value, dict):
            return int(value.get("outputTokens") or 0)
        return 0

    # Sort by output tokens descending; tiebreak on model id ascending so
    # the winner is deterministic when outputs tie (e.g. both zero).
    return sorted(
        model_usage.items(),
        key=lambda kv: (-_output_tokens(kv[1]), kv[0]),
    )[
        0
    ][0]


class SessionAccumulator:
    """Accumulate per-query usage into session-scoped totals.

    Counters grow monotonically within a session. Unlike the CLI (where
    ``/clear`` preserves process-scoped totals because the subprocess
    stays alive), the dashboard's clear tears down the SDK subprocess
    and spawns a new one — a new PID, a new process from AgentPulse's
    perspective. Call ``reset()`` on clear so each session starts fresh.
    """

    def __init__(self) -> None:
        self.session_id: str = ""
        self.total_cost_usd: float = 0.0
        self.total_input_tokens: int = 0
        self.total_output_tokens: int = 0
        self.total_duration_ms: int = 0
        self.total_api_duration_ms: int = 0
        # Snapshot of the most recent turn's usage — used for
        # ``used_percentage`` which must reflect *current* context size,
        # not lifetime totals. Cumulative counters above grow without
        # bound and can't represent present context window occupancy.
        self.last_input_tokens: int = 0
        self.last_cache_read_tokens: int = 0
        self.last_cache_creation_tokens: int = 0
        self.last_model_name: str = ""

    def record_result(
        self,
        *,
        session_id: str,
        total_cost_usd: float | None,
        usage: dict[str, Any] | None,
        duration_ms: int,
        duration_api_ms: int,
        model_name: str = "",
    ) -> None:
        """Accumulate lifetime counters from a ``ResultMessage``.

        The CLI's ``ResultMessage.usage`` is aggregated across every API
        call in the turn (tool loops produce many calls), so its token
        counts are sums — appropriate for lifetime totals but NOT for
        representing current context size. Use ``record_turn_snapshot``
        for the per-call snapshot that feeds ``used_percentage``.
        """
        self.session_id = session_id
        if total_cost_usd is not None:
            self.total_cost_usd += float(total_cost_usd)
        self.total_duration_ms += int(duration_ms or 0)
        self.total_api_duration_ms += int(duration_api_ms or 0)
        if usage:
            self.total_input_tokens += int(usage.get("input_tokens") or 0)
            self.total_output_tokens += int(usage.get("output_tokens") or 0)
        if model_name:
            self.last_model_name = model_name

    def reset(self) -> None:
        """Zero all counters — call on clear (new subprocess = new process)."""
        self.session_id = ""
        self.total_cost_usd = 0.0
        self.total_input_tokens = 0
        self.total_output_tokens = 0
        self.total_duration_ms = 0
        self.total_api_duration_ms = 0
        self.reset_snapshot()

    def reset_snapshot(self) -> None:
        """Zero the per-turn snapshot so context % reads 0 until the next turn."""
        logger.debug("snapshot reset to zero")
        self.last_input_tokens = 0
        self.last_cache_read_tokens = 0
        self.last_cache_creation_tokens = 0

    def record_turn_snapshot(self, usage: dict[str, Any] | None) -> None:
        """Record per-API-call usage from the turn's last AssistantMessage.

        This is the single-call view — input + cache_read + cache_creation
        from one API request — so it cannot exceed the context window and
        correctly represents present context occupancy.
        """
        if not usage:
            logger.debug("snapshot: no usage provided, keeping previous values")
            return
        self.last_input_tokens = int(usage.get("input_tokens") or 0)
        self.last_cache_read_tokens = int(usage.get("cache_read_input_tokens") or 0)
        self.last_cache_creation_tokens = int(
            usage.get("cache_creation_input_tokens") or 0
        )
        logger.debug(
            "snapshot: input=%d cache_read=%d cache_create=%d",
            self.last_input_tokens,
            self.last_cache_read_tokens,
            self.last_cache_creation_tokens,
        )


def build_payload(
    acc: SessionAccumulator,
    *,
    pid: int,
    cwd: str,
    source_system: str,
) -> dict[str, Any]:
    """Build the statusline JSON body AgentPulse expects.

    Leaves ``cost.total_lines_added`` and ``cost.total_lines_removed``
    unset — the SDK doesn't expose tool-result diff counts.
    """
    window_size = lookup_context_window(acc.last_model_name)
    # ``used_percentage`` reflects the most recent turn's context size,
    # matching the CLI statusline hook's semantics. Using cumulative
    # ``total_input_tokens`` here would grow without bound and push the
    # percentage past 100% over a long-lived process.
    ctx_used = (
        acc.last_input_tokens
        + acc.last_cache_read_tokens
        + acc.last_cache_creation_tokens
    )
    used_pct = (ctx_used / window_size * 100) if window_size else 0.0
    logger.debug(
        "context %%: model=%s window=%d input=%d cache_read=%d "
        "cache_create=%d total=%d pct=%.1f",
        acc.last_model_name,
        window_size,
        acc.last_input_tokens,
        acc.last_cache_read_tokens,
        acc.last_cache_creation_tokens,
        ctx_used,
        used_pct,
    )
    return {
        "session_id": acc.session_id,
        "pid": pid,
        "source_system": source_system,
        "workspace": {"project_dir": cwd},
        "cost": {
            "total_cost_usd": acc.total_cost_usd,
            "total_duration_ms": acc.total_duration_ms,
            "total_api_duration_ms": acc.total_api_duration_ms,
        },
        "context_window": {
            "total_input_tokens": acc.total_input_tokens,
            "total_output_tokens": acc.total_output_tokens,
            "used_percentage": round(used_pct, 1),
            "context_window_size": window_size,
            "current_usage": {
                "input_tokens": acc.last_input_tokens,
                "cache_read_input_tokens": acc.last_cache_read_tokens,
                "cache_creation_input_tokens": acc.last_cache_creation_tokens,
            },
        },
        "model": {"display_name": acc.last_model_name},
    }


class SeedResult:
    """Outcome of a one-shot seed attempt against AgentPulse.

    ``ok`` is True when the accumulator may now be POSTed. This covers
    two sub-cases:

    - ``merged=True``: AgentPulse returned a record for this session.
      Any non-null stored totals were *added* to the accumulator's
      local values so the resulting counters represent (prior persisted)
      + (locally accumulated while offline). A response with every
      numeric field null still reports ``merged=True`` — AgentPulse had
      the session but had nothing to contribute.
    - ``merged=False``: AgentPulse was reachable but had no record of
      this session. The accumulator is left untouched — its local
      values are already authoritative.

    ``ok`` is False only when AgentPulse was unreachable or returned an
    unexpected error. The caller must not POST in that state; the
    accumulator keeps growing locally until a later seed attempt
    succeeds.
    """

    __slots__ = ("ok", "merged")

    def __init__(self, *, ok: bool, merged: bool) -> None:
        self.ok = ok
        self.merged = merged


def merge_agentpulse_seed(
    acc: SessionAccumulator,
    session: Session | None,
) -> SeedResult:
    """Add AgentPulse's stored session totals to ``acc`` (one-shot).

    Designed to run exactly once per process lifetime, the first time
    AgentPulse is reachable after startup. The accumulator may already
    contain local counters from ResultMessages received while AgentPulse
    was offline; those counters are preserved and the stored totals are
    *added* so no data is lost in either direction.

    ``session`` is the ``Session`` dataclass returned by
    ``AgentPulseClient.session(id)`` — ``None`` when the session is
    unknown to AgentPulse (client returns None on 404 or failure).

    Fields merged (all additive):
    - ``total_cost_usd``
    - ``total_input_tokens``
    - ``total_output_tokens``

    ``last_model_name`` is populated from AgentPulse only if the
    accumulator hasn't seen one yet (local takes precedence because it
    came from an actual SDK message).
    """
    if session is None:
        return SeedResult(ok=True, merged=False)

    acc.session_id = session.session_id
    acc.total_cost_usd += session.total_cost_usd
    acc.total_input_tokens += session.total_input_tokens
    acc.total_output_tokens += session.total_output_tokens
    if session.model_name and not acc.last_model_name:
        acc.last_model_name = session.model_name
    return SeedResult(ok=True, merged=True)
